from decimal import Decimal


_ZERO = Decimal(0)
_HUNDRED = Decimal(100)


def _as_decimal(value: object) -> Decimal:
    """Apply legacy NVL(value, 0) numeric coercion."""
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        return value
    if isinstance(value, bool):
        return Decimal(int(value))
    return Decimal(str(value))


def _parts(value: Decimal) -> tuple[int, int]:
    """Return a signed integer coefficient and base-10 exponent."""
    data = value.as_tuple()
    coefficient = 0
    for digit in data.digits:
        coefficient = coefficient * 10 + digit
    if data.sign:
        coefficient = -coefficient
    return coefficient, data.exponent


def _from_parts(coefficient: int, exponent: int) -> Decimal:
    if coefficient == 0:
        return Decimal((0, (0,), exponent))

    sign = int(coefficient < 0)
    digits = Decimal(abs(coefficient)).as_tuple().digits
    return Decimal((sign, digits, exponent))


def _multiply_exact(left: Decimal, right: Decimal) -> Decimal:
    left_coefficient, left_exponent = _parts(left)
    right_coefficient, right_exponent = _parts(right)
    return _from_parts(
        left_coefficient * right_coefficient,
        left_exponent + right_exponent,
    )


def _subtract_exact(left: Decimal, right: Decimal) -> Decimal:
    left_coefficient, left_exponent = _parts(left)
    right_coefficient, right_exponent = _parts(right)
    common_exponent = min(left_exponent, right_exponent)

    coefficient = (
        left_coefficient * (10 ** (left_exponent - common_exponent))
        - right_coefficient * (10 ** (right_exponent - common_exponent))
    )
    return _from_parts(coefficient, common_exponent)


def _shift_decimal(value: Decimal, places: int) -> Decimal:
    coefficient, exponent = _parts(value)
    return _from_parts(coefficient, exponent + places)


def _round_cents(value: Decimal) -> Decimal:
    """Round half-up to two decimal places using exact integer arithmetic."""
    coefficient, exponent = _parts(value)

    if exponent >= -2:
        cents = coefficient * (10 ** (exponent + 2))
        return _from_parts(cents, -2)

    divisor = 10 ** (-2 - exponent)
    magnitude, remainder = divmod(abs(coefficient), divisor)
    if remainder * 2 >= divisor:
        magnitude += 1

    cents = -magnitude if coefficient < 0 else magnitude
    return _from_parts(cents, -2)


def _cents_integer(value: Decimal) -> int:
    coefficient, exponent = _parts(value)
    return coefficient * (10 ** (exponent + 2))


def recompute(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list]:
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    total_cents = 0

    for line in new_lines:
        if line.get("DEL_FLG") == "Y":
            continue

        quantity = _as_decimal(line.get("QTY", ""))
        unit_price = _as_decimal(line.get("UNIT_PRC", ""))
        extended = _round_cents(_multiply_exact(quantity, unit_price))

        line["EXT_AMT"] = float(extended)
        total_cents += _cents_integer(extended)

    total = _from_parts(total_cents, -2)
    discount = _as_decimal(order.get("DISC_PCT", ""))
    discount_factor = _subtract_exact(_HUNDRED, discount)
    discounted_unrounded = _shift_decimal(
        _multiply_exact(total, discount_factor),
        -2,
    )
    discounted = _round_cents(discounted_unrounded)

    incoming_total = _as_decimal(order.get("TOT_AMT", ""))
    new_order["TOT_AMT"] = float(discounted)

    audits = []
    if incoming_total != discounted:
        audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
